extracted_python_code:
customer_signups_and_transactions = Broker.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_period) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS("-", YEAR(join_date), LPAD(MONTH(join_date), 2, "0"))
).PARTITION(
    name="monthly_signups", by=signup_month
).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
).ORDER_BY(month.ASC())

acp_by_type = DailyPrices.WHERE(
    DATEDIFF("days", date, DATETIME('now')) <= 6
).CALCULATE(
    type_of_ticker=ticker.ticker_type
).PARTITION(
    name="type_groups", by=(type_of_ticker,)
).CALCULATE(
    ticker_type=type_of_ticker,
    average_closing_price=AVG(DailyPrices.close)
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

filtered_transactions = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
)

transaction_summary = filtered_transactions.PARTITION(
    name="transaction_groups", by=transaction_type
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
)

top_transaction_types = transaction_summary.TOP_K(
    3, by=num_distinct_customers.DESC()
)

distinct_ticker_ids = DailyPrices.WHERE(date >= '2023-04-01').PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

top_countries_by_amount = Transactions.WHERE(
    DATEDIFF("days", date_time, 'now') <= 30
).CALCULATE(
    country_name=customer.country
).PARTITION(
    name="countries", by=(country_name)
).CALCULATE(
    country=country_name,
    number_of_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(
    5, by=total_transaction_amount.DESC()
)

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & 
            (DATEDIFF("days", date, DATETIME('now')) <= 7)
        ).close
    )
)

asp_q1_2023 = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

avg_payment_time = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(
                HAS(payment) == 1
            ).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

total_sales_count = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

distinct_customer_ids = Sales.PARTITION(name="customer_groups", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

distinct_salespersons_with_cash_payment = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

shortest_employment_salesperson = Salespersons.WHERE(
    PRESENT(termination_date)
).CALCULATE(
    days_employed=DATEDIFF("days", hire_date, termination_date)
).TOP_K(
    1, by=days_employed.ASC()
).CALCULATE(
    salesperson_name=JOIN_STRINGS(" ", first_name, last_name),
    phone_number=phone,
    days_employed=days_employed
)

weekend_payments_to_utility = Dealership.CALCULATE(
    weekend_utility_payments_count=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ("Saturday", "Sunday"))
        )
    )
)

inventory_cars = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
).WHERE(
    RANKING(by=snapshot_date.DESC(), allow_ties=True) == 1
).WHERE(
    is_in_inventory == True
).car.CALCULATE(
    _id,
    make,
    model,
    year
)

avg_ddd_per_drug = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            (PRESENT(end_dt) == 1) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), '@gmail.com') | ENDSWITH(LOWER(email), '@yahoo.com')
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (LOWER(diagnosis.diag_name) == LOWER('Psoriasis vulgaris')) &
                    (LOWER(drug.drug_type) == LOWER('Biologic'))
                )
            ) == 1
        )
    )
)

alice_treatments_in_last_6_months = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    six_months_ago=DATETIME('now', 'start of month', '-6 months')
).CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(LOWER(first_name) == 'alice').treatments_received.WHERE(
            (start_dt >= six_months_ago) & (start_dt < start_of_current_month)
        )
    )
)

result = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_12_months_ago=DATETIME('now', 'start of month', '-12 months')
).Treatments.WHERE(
    (start_dt >= start_of_12_months_ago) & (start_dt < start_of_current_month)
).CALCULATE(
    treatment_month=DATETIME(start_dt, 'start of month')
).PARTITION(name="monthly_groups", by=(treatment_month)).CALCULATE(
    month=treatment_month,
    PMTC=COUNT(Treatments),
    PMPD=NDISTINCT(Treatments.CALCULATE(patient_diag_key=JOIN_STRINGS('-', patient_id, diag_id)).patient_diag_key)
).ORDER_BY(month.ASC())

result = DermTreatment.CALCULATE(
    avg_weight=AVG(Drugs.WHERE(LOWER(drug_name) == 'drugalin').treatments_used_in.patient.weight_kg)
)

caw_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(LOWER(gender) == 'male').weight_kg)
)

npi_by_year = DermTreatment.Patients.CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_groups", by=first_treatment_year
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).ORDER_BY(year.ASC()).CALCULATE(
    year=year,
    num_new_patients=num_new_patients,
    NPINPI=num_new_patients - PREV(num_new_patients, by=year.ASC(), default=0)
)

overall_d7d100pir = DermTreatment.CALCULATE(
    avg_pasi_d7=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day7_pasi_score),
    avg_pasi_d100=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day100_pasi_score)
).CALCULATE(
    d7d100pir=(avg_pasi_d100 - avg_pasi_d7) / avg_pasi_d7 * 100.0
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) & (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

doctor_states_for_biologics = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

top_insurance_types_by_pasi = DermTreatment.Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=(insurance_type)
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score_100=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(5, by=avg_pasi_score_100.ASC())

psoriasis_treatments_last_6_months = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            LIKE(LOWER(diagnosis.diag_name), '%psoriasis%') &
            PRESENT(drug.fda_appr_dt) &
            (end_dt >= DATETIME('now', '-6 months'))
        )
    )
)

avg_age_of_patients = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, 'now')
        ).age_in_years
    )
)

result = Merchants.CALCULATE(
    merchant_name=name,
    cpur=NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).WHERE(
            PRESENT(coupon_id)
        ).coupon_id
    ) / NDISTINCT(
        transactions_received.WHERE(
            LOWER(status) == LOWER("successful")
        ).txid
    )
)

result = Ewallet.CALCULATE(
    num_transactions=COUNT(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        )
    ),
    total_amount=SUM(
        Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME('now')) <= 7
        ).amount
    )
)

lub_per_user = Users.CALCULATE(
    user_id=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

user_marketing_preference = Ewallet.Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

user_session_durations = Users.CALCULATE(
    user_id=uid,
    total_duration=ROUND(SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    ), 0)
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

tuc_result = Ewallet.CALCULATE(
    tuc_count=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

distinct_receiving_merchants = Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

distinct_transaction_notification_users = Notifications.WHERE(
    LOWER(notification_type) == 'transaction'
).PARTITION(
    name='distinct_users', by=user_id
).CALCULATE(
    user_id
)

top_countries_by_amount_sent = Ewallet.Transactions.WHERE(sender_type == 0).CALCULATE(
    sender_country=sending_user.country
).PARTITION(
    name="countries", by=(sender_country)
).CALCULATE(
    country=sender_country,
    total_transaction_amount=SUM(Transactions.amount),
    num_distinct_users=NDISTINCT(Transactions.sender_id)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (LOWER(status) == 'active') & 
            (CONTAINS(LOWER(category), 'retail'))
        ).balances.WHERE(
            updated_at >= DATETIME('now', 'start of day')
        ).balance
    )
)

# First, find the earliest snapshot date in 2023
earliest_date_2023 = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).CALCULATE(
    min_date=MIN(UserSettingSnapshots.snapshot_date)
).SINGULAR().min_date

# Then calculate the averages for that specific date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_monthly
    )
)

users_without_first_year_notification = Users.CALCULATE(
    one_year_anniversary=DATETIME(created_at, '1 year')
).WHERE(
    HAS(notifications.WHERE(created_at <= one_year_anniversary)) == 0
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
